style.css:
@-moz-document url-prefix("https://www.youtube.com") {
/* Subscribe button */
  ytd-subscribe-button-renderer tp-yt-paper-button {
    background-color: #ffe4ec !important;
    color: #ff69b4 !important;
    border: 1px solid #ffb6c1 !important;
  }

  ytd-subscribe-button-renderer tp-yt-paper-button:hover {
    background-color: #ffcadd !important;
    color: #ffffff !important;
  }

  /* Like and Dislike button colors */
  ytd-toggle-button-renderer[is-icon-button] tp-yt-paper-button {
    color: #ffb6c1 !important;
    border-color: transparent !important;
  }

  ytd-toggle-button-renderer[is-icon-button] tp-yt-paper-button:hover {
    background-color: #ffcadd !important;
    color: #ffffff !important;
  }

  /* Icons for Home, Shorts, Subscriptions, etc. */
  ytd-mini-guide-entry-renderer yt-icon,
  ytd-guide-entry-renderer yt-icon,
  ytd-guide-entry-renderer svg {
    fill: #ffb6c1 !important;
    color: #ffb6c1 !important;
  }

  /* Hover state for sidebar icons */
  ytd-guide-entry-renderer:hover yt-icon,
  ytd-mini-guide-entry-renderer:hover yt-icon {
    fill: #ff69b4 !important;
    color: #ff69b4 !important;
  }

  /* Change icon color when selected */
  ytd-guide-entry-renderer[aria-selected="true"] yt-icon,
  ytd-mini-guide-entry-renderer[aria-selected="true"] yt-icon {
    fill: #ff69b4 !important;
    color: #ff69b4 !important;
  }
}
